import React from "react";
import Button from '@mui/material/Button';

const account = 0;

function Account(){
    if (account === 0)
    {
        return(
        <div>
            Changer de compte
            <br/>
            <Button variant="contained">Clement</Button>
            <br/>
            <Button variant="contained">Alexandre</Button>
            <br/>
        </div>
        )
        account=1;
    }

    if (account === 1)
    {
        return(
        <div>
            Changer de compte
            <br/>
            <Button variant="contained">Clement</Button>
            <br/>
            <Button variant="contained">Alexandre</Button>
            <br/>
        </div>
        )
        account=0;
    }
}

function Logout(){
    return(
        <div>
            Changer de compte
            <br/>
            
            <Button variant="contained">Clement</Button>
            <br/>
            <Button variant="contained">Alexandre</Button>
            <br/>
        </div>
    )
}

export default Logout
